    let _args: Vec<String> = std::env::args().collect();

    let mut out = std::io::stdout();

    let mut bar = ProgressBar::new();
    bar.set_progress(75);
    bar.set_total(100);
    bar.set_width(30);
    let _ = writeln!(out, "{}", bar.str());
    let _ = out.flush();

    let pct = Percentage::new(0.75);
